function Repository() {
  const [location, navigate] = useLocation();
  const queryParam = new URLSearchParams(location.split("?")[1] ?? "").get("q") ?? "";
  const [query, setQuery] = useState(queryParam);
  const [type, setType] = useState<(typeof contentTypes)[number]>("All types");
  const [region, setRegion] = useState<(typeof allRegions)[number]>("All regions");
  const [year, setYear] = useState("All years");
  const [topic, setTopic] = useState("All topics");
  const [sort, setSort] = useState("relevance");
  const [saved, setSaved] = useState<string[]>([]);
  const [items, setItems] = useState<typeof repositoryItems>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState("");
  useEffect(() => {
    let active = true;
    setLoading(true);
    getRepository({ query, type, region, year, topic, sort })
      .then((result) => {
        if (!active) return;
        setItems(result.items);
        setTotal(result.total);
        setLoadError("");
      })
      .catch(() => {
        if (active) setLoadError("The repository could not be loaded from the backend.");
      })
      .finally(() => {
        if (active) setLoading(false);
      });
    return () => { active = false; };
  }, [query, type, region, year, topic, sort]);
  const filtered = items;
  const clear = () => { setQuery(""); setType("All types"); setRegion("All regions"); setYear("All years"); setTopic("All topics"); setSort("relevance"); navigate("/repository"); };
  return <><Header /><PageIntro eyebrow="Knowledge repository" title="A public record of polar work." description={repositoryDescription}><div className="mt-9 max-w-3xl"><SearchField value={query} onChange={setQuery} onSubmit={() => navigate(`/repository${query ? `?q=${encodeURIComponent(query)}` : ""}`)} /></div><div className="mt-4 flex flex-wrap gap-2">{promptChips.map((chip) => <button key={chip} onClick={() => setQuery(chip)} className="rounded-full border border-[#d5e4ea] bg-white px-3 py-2 text-xs font-semibold text-[#5e7180] transition hover:border-cyan-300 hover:bg-cyan-50 hover:text-cyan-800">{chip}</button>)}</div></PageIntro><main className="bg-[#f4f8fb]"><div className="container py-12 md:py-16"><div className="flex flex-col gap-5 border-b border-[#dbe7ec] pb-6 lg:flex-row lg:items-center lg:justify-between"><div><p className="text-sm font-semibold text-[#102333]">{loading ? "Loading records..." : `${total} records`} <span className="font-normal text-[#91a2a9]">in the public index</span></p><p className="mt-1 text-xs text-[#7b8f99]">Search by source, topic, region or format.</p></div><div className="flex flex-wrap gap-2"><Select value={type} onChange={(value) => setType(value as (typeof contentTypes)[number])} options={contentTypes as unknown as string[]} /><Select value={region} onChange={(value) => setRegion(value as (typeof allRegions)[number])} options={allRegions as unknown as string[]} /><Select value={year} onChange={setYear} options={["All years", "2024", "2023", "2022", "2021", "2020"]} /><Select value={topic} onChange={setTopic} options={["All topics", ...allTopics]} /><Select value={sort} onChange={setSort} options={["relevance", "newest", "oldest"]} /></div></div><div className="mt-8 flex items-center justify-between gap-3"><div className="flex items-center gap-2 text-xs font-semibold text-[#7b8f99]"><Filter className="h-4 w-4 text-cyan-700" /> Filters active <span className="text-cyan-700">{[type !== "All types", region !== "All regions", year !== "All years", topic !== "All topics"].filter(Boolean).length}</span></div><button onClick={clear} className="text-xs font-semibold text-cyan-700 hover:text-cyan-900">Clear all</button></div>{loadError ? <div className="mt-8 rounded-2xl border border-red-200 bg-red-50 p-5 text-sm text-red-800">{loadError}</div> : filtered.length ? <div className="mt-6 grid gap-5 md:grid-cols-2 lg:grid-cols-3">{filtered.map((item) => <RecordCard key={item.id} item={item} saved={saved.includes(item.id)} onSave={() => setSaved((current) => current.includes(item.id) ? current.filter((id) => id !== item.id) : [...current, item.id])} />)}</div> : !loading && <EmptyState onClear={clear} />}</div></main><Footer /></>;
}

function Select({ value, onChange, options }: { value: string; onChange: (value: string) => void; options: string[] }) {
  return <label className="relative"><span className="sr-only">Filter</span><select value={value} onChange={(event) => onChange(event.target.value)} className="h-10 appearance-none rounded-full border border-[#d5e4ea] bg-white py-2 pl-4 pr-9 text-xs font-semibold text-[#5e7180] outline-none transition hover:border-cyan-300 focus:border-cyan-400 focus:ring-4 focus:ring-cyan-100">{options.map((option) => <option key={option} value={option}>{option}</option>)}</select><ChevronDown className="pointer-events-none absolute right-3 top-3 h-3.5 w-3.5 text-[#7b8f99]" /></label>;
}

function EmptyState({ onClear }: { onClear: () => void }) { return <div className="mt-8 rounded-[2rem] border border-dashed border-[#c9dde4] bg-white px-6 py-16 text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-cyan-50 text-cyan-700"><Search className="h-6 w-6" /></div><h3 className="mt-6 font-display text-2xl font-semibold tracking-[-0.04em] text-[#102333]">No sources found.</h3><p className={cx("mx-auto mt-3 max-w-md", bodyCopyClass)}>Try a broader topic, another year, or clear one of the filters.</p><button onClick={onClear} className="mt-6 rounded-full bg-[#102333] px-5 py-3 text-sm font-semibold text-white transition hover:bg-[#163b55]">Reset the index</button></div>; }

function RepositoryDetail({ id }: { id: string }) {
  const item = getItem(id) ?? featuredExpedition;
  return <><Header /><main className="bg-[#f4f8fb] pt-28 md:pt-36"><div className="container pb-20 md:pb-28"><Link href="/repository" className="inline-flex items-center gap-2 text-sm font-semibold text-cyan-700 hover:text-cyan-900">← Back to repository</Link><div className="mt-10 grid gap-10 lg:grid-cols-[1.1fr_.9fr]"><div><Tag className={colorForType[item.type]}>{item.icon} {item.type}</Tag><h1 className="mt-6 max-w-3xl font-display text-5xl font-semibold leading-[.95] tracking-[-0.065em] text-[#102333] md:text-7xl">{item.title}</h1><p className={cx("mt-7 max-w-2xl text-lg", bodyCopyClass)}>{item.summary}</p><div className="mt-8 flex flex-wrap gap-2">{item.topics.map((topic) => <span key={topic} className="rounded-full bg-white px-3 py-2 text-xs font-semibold text-[#607984] shadow-sm">{topic}</span>)}</div></div><div className={cx("relative min-h-[330px] overflow-hidden rounded-[2rem] bg-gradient-to-br p-8", item.accent)}><div className="absolute inset-0 bg-[radial-gradient(circle_at_75%_20%,rgba(255,255,255,.6),transparent_28%)]" /><div className="relative flex h-full flex-col justify-between"><div className="flex items-center justify-between"><span className="grid h-14 w-14 place-items-center rounded-2xl bg-white/70 text-2xl text-[#102333] shadow-sm">{item.icon}</span><span className="font-display text-8xl font-semibold tracking-[-0.1em] text-[#102333]/10">{item.year}</span></div><div><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-[#102333]/50">Institutional source preview</p><p className="mt-2 max-w-xs font-display text-2xl font-semibold leading-tight text-[#102333]">Trace the record. Follow the question.</p></div></div></div></div><div className="mt-14 grid gap-5 md:grid-cols-3"><InfoTile label="Year" value={String(item.year)} /><InfoTile label="Region" value={item.region} /><InfoTile label="Format" value={item.meta} /></div><div className="mt-14 grid gap-10 lg:grid-cols-[1.2fr_.8fr]"><div className="rounded-[2rem] border border-[#dbe7ec] bg-white p-7 md:p-10"><div className="flex items-center justify-between gap-4"><h2 className="font-display text-3xl font-semibold tracking-[-0.05em] text-[#102333]">Source abstract</h2><button className="inline-flex items-center gap-2 rounded-full border border-[#dbe7ec] px-3 py-2 text-xs font-semibold text-[#5e7180] hover:border-cyan-300 hover:bg-cyan-50"><ExternalLink className="h-3.5 w-3.5" /> Open file</button></div><p className={cx("mt-6 text-base", bodyCopyClass)}>This prototype record represents the kind of trusted source POLARIS is designed to make discoverable. In production, the abstract, metadata, source file and related assets will be pulled from NCPOR’s institutional repository with a permanent citation link.</p><div className="mt-8 rounded-2xl bg-[#f4f8fb] p-5"><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-cyan-700">Why it matters</p><p className="mt-3 text-sm leading-6 text-[#5e7180]">Every source becomes more valuable when a student can find it, a researcher can cite it, and an outreach team can explain it without losing the evidence.</p></div></div><div><p className="text-[11px] font-bold uppercase tracking-[0.2em] text-cyan-700">Related records</p><div className="mt-5 grid gap-3">{repositoryItems.filter((candidate) => candidate.id !== item.id).slice(0, 3).map((related) => <Link key={related.id} href={`/repository/${related.id}`} className="group rounded-2xl border border-[#dbe7ec] bg-white p-4 transition hover:-translate-y-0.5 hover:border-cyan-200"><div className="flex items-center gap-3"><span className={cx("grid h-9 w-9 place-items-center rounded-xl text-xs", colorForType[related.type])}>{related.icon}</span><div className="min-w-0"><p className="truncate text-sm font-semibold text-[#102333] group-hover:text-cyan-800">{related.title}</p><p className="mt-1 text-xs text-[#80939d]">{related.type} · {related.year}</p></div></div></Link>)}</div></div></div></div></main><Footer /></>;
}

function InfoTile({ label, value }: { label: string; value: string }) { return <div className="rounded-2xl border border-[#dbe7ec] bg-white p-5"><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-[#91a2a9]">{label}</p><p className="mt-3 font-display text-xl font-semibold tracking-[-0.04em] text-[#102333]">{value}</p></div>; }

function Assistant() {
  const [prompt, setPrompt] = useState("");
  const [messages, setMessages] = useState<Array<{ role: "user" | "assistant"; text: string }>>([]);
  const [sources, setSources] = useState<AssistantSource[]>([]);
  const [loading, setLoading] = useState(false);
  const [simple, setSimple] = useState(false);
  const ask = async (value = prompt) => { if (!value.trim() || loading) return; const question = value.trim(); setMessages((current) => [...current, { role: "user", text: question }]); setPrompt(""); setLoading(true); try { const response = await queryAssistant(question, simple); setMessages((current) => [...current, { role: "assistant", text: simple ? response.simplifiedAnswer : response.detailedAnswer }]); setSources(response.sources); } catch { setMessages((current) => [...current, { role: "assistant", text: "The assistant is temporarily unavailable. Please check that the backend and its AI services are running." }]); } finally { setLoading(false); } };
  return <><Header /><PageIntro eyebrow="AI polar assistant" title="Ask the archive a better question." description={assistantDescription} dark><div className="mt-9 flex flex-wrap gap-2">{promptChips.map((chip) => <button key={chip} onClick={() => ask(chip)} className="rounded-full border border-white/15 bg-white/5 px-3 py-2 text-xs text-white/65 transition hover:border-cyan-200/50 hover:bg-white/10 hover:text-white">{chip}</button>)}</div></PageIntro><main className="bg-[#f4f8fb]"><div className="container grid gap-6 py-12 md:py-16 lg:grid-cols-[1fr_320px]"><section className="overflow-hidden rounded-[2rem] border border-[#dbe7ec] bg-white shadow-[0_20px_60px_rgba(8,28,45,0.08)]"><div className="flex items-center justify-between border-b border-[#e5edf0] px-6 py-5 md:px-8"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-cyan-100 text-cyan-800"><Sparkles className="h-5 w-5" /></span><div><p className="text-sm font-semibold text-[#102333]">POLARIS assistant</p><p className="text-xs text-[#80939d]">Grounded in the knowledge repository</p></div></div><label className="flex items-center gap-2 text-xs font-semibold text-[#5e7180]"><span className={cx("relative h-5 w-9 rounded-full transition", simple ? "bg-cyan-500" : "bg-[#dbe7ec]")}><input type="checkbox" checked={simple} onChange={(event) => setSimple(event.target.checked)} className="sr-only" /><span className={cx("absolute top-1 h-3 w-3 rounded-full bg-white shadow transition", simple ? "left-5" : "left-1")} /></span> Class 10 mode</label></div><div className="min-h-[440px] space-y-5 p-6 md:p-8">{messages.length === 0 ? <div className="flex min-h-[340px] flex-col items-center justify-center text-center"><div className="grid h-16 w-16 place-items-center rounded-[1.5rem] bg-[#e5f3f8] text-cyan-700"><MessageCircle className="h-7 w-7" /></div><h2 className="mt-6 font-display text-3xl font-semibold tracking-[-0.05em] text-[#102333]">What are you curious about?</h2><p className={cx("mt-3 max-w-md", bodyCopyClass)}>Try a question about an expedition, station or the science behind a polar observation.</p></div> : messages.map((message, index) => <div key={`${message.role}-${index}`} className={cx("flex gap-3", message.role === "user" ? "justify-end" : "justify-start")}><div className={cx("max-w-[80%] rounded-[1.5rem] px-5 py-4 text-sm leading-7", message.role === "user" ? "bg-[#102333] text-white" : "bg-[#e5f3f8] text-[#294755]")}>{message.text}{message.role === "assistant" && <div className="mt-4 flex flex-wrap gap-2 border-t border-cyan-900/10 pt-3 text-[10px] font-semibold uppercase tracking-[0.1em] text-cyan-800"><span><CheckCircle2 className="mr-1 inline h-3.5 w-3.5" /> Grounded answer</span><span>{sources.length} source records</span></div>}</div></div>)}</div><div className="border-t border-[#e5edf0] p-5 md:p-6"><form onSubmit={(event) => { event.preventDefault(); ask(); }} className="flex items-center gap-3 rounded-2xl border border-[#d5e4ea] bg-[#f4f8fb] p-2 pl-4 focus-within:border-cyan-400 focus-within:ring-4 focus-within:ring-cyan-100"><input value={prompt} onChange={(event) => setPrompt(event.target.value)} placeholder="Ask about a station, expedition or topic..." className="min-w-0 flex-1 bg-transparent text-sm text-[#102333] outline-none placeholder:text-[#91a2a9]" /><button type="submit" className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[#102333] text-white transition hover:bg-[#163b55] disabled:opacity-40" disabled={!prompt.trim() || loading} aria-label="Send question"><Send className="h-4 w-4" /></button></form><p className="mt-3 text-center text-[10px] text-[#91a2a9]">Live response from the Polar Connect backend.</p></div></section><aside className="space-y-5"><div className="rounded-[1.5rem] border border-[#dbe7ec] bg-white p-6"><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-cyan-700">Cited sources</p><div className="mt-5 space-y-3">{sources.length ? sources.map((source) => <div key={source.id} className="rounded-2xl bg-[#f4f8fb] p-4"><div className="flex gap-3"><FileText className="mt-0.5 h-4 w-4 shrink-0 text-cyan-700" /><p className="text-xs font-semibold leading-5 text-[#294755]">{source.title} · {source.type}</p></div></div>) : <p className="text-xs leading-5 text-[#80939d]">Sources will appear after your first question.</p>}</div><Link href="/repository" className="mt-5 inline-flex items-center gap-2 text-xs font-semibold text-cyan-700">Browse the repository <ArrowUpRight className="h-3.5 w-3.5" /></Link></div><div className="rounded-[1.5rem] bg-[#102333] p-6 text-white"><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-cyan-200/80">Try this next</p><p className="mt-4 font-display text-2xl font-semibold leading-tight tracking-[-0.04em]">“Teach me this topic.”</p><p className="mt-3 text-sm leading-6 text-white/55">Turn an answer into a lesson, then test what you remember.</p><Link href="/learn" className="mt-6 inline-flex items-center gap-2 rounded-full bg-cyan-300 px-4 py-2.5 text-xs font-semibold text-[#071525]">Open learning <ArrowUpRight className="h-3.5 w-3.5" /></Link></div></aside></div></main><Footer /></>;
}

function Learn() {
  return <><Header /><PageIntro eyebrow="Smart learning" title="Big science. Clear next steps." description={learnDescription}><div className="mt-8 flex flex-wrap gap-2"><Tag className="bg-[#102333] text-white">6 learning paths</Tag><Tag className="border border-[#d5e4ea] bg-white text-[#5e7180]">Progress saved in this demo</Tag></div></PageIntro><main className="bg-[#f4f8fb]"><div className="container py-12 md:py-16"><div className="mb-8 flex items-end justify-between gap-4"><div><p className="text-sm font-semibold text-[#102333]">Choose a path</p><p className="mt-1 text-xs text-[#80939d]">Start simple, go deeper when you are ready.</p></div><div className="hidden items-center gap-2 text-xs font-semibold text-[#80939d] sm:flex"><span className="h-2 w-2 rounded-full bg-cyan-500" /> 1 of 6 in progress</div></div><div className="grid gap-5 md:grid-cols-2 lg:grid-cols-3">{learningTopics.map((topic, index) => <Link key={topic.id} href={`/learn/${topic.id}`} className="group relative overflow-hidden rounded-[1.7rem] border border-[#dbe7ec] bg-white p-6 transition duration-300 hover:-translate-y-1 hover:border-cyan-200 hover:shadow-[0_20px_60px_rgba(8,28,45,0.1)]"><div className={cx("absolute inset-x-0 top-0 h-24 bg-gradient-to-br opacity-70", topicColorMap[topic.color])} /><div className="relative flex items-center justify-between"><span className="text-[10px] font-bold uppercase tracking-[0.18em] text-cyan-700">{topic.tag}</span><span className="font-display text-4xl font-semibold tracking-[-0.08em] text-[#dbe9ed]">0{index + 1}</span></div><h2 className="relative mt-16 max-w-xs font-display text-2xl font-semibold leading-tight tracking-[-0.045em] text-[#102333] group-hover:text-cyan-800">{topic.title}</h2><p className={cx("relative mt-3", bodyCopyClass)}>{topic.description}</p><div className="relative mt-7"><div className="flex items-center justify-between text-[10px] font-semibold text-[#80939d]"><span>Progress</span><span>{topic.progress}%</span></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-[#e5edf0]"><div className="h-full rounded-full bg-cyan-500" style={{ width: `${topic.progress}%` }} /></div></div><div className="relative mt-6 flex items-center justify-between text-xs font-semibold text-cyan-700"><span>{topic.progress ? "Continue learning" : "Open lesson"}</span><ArrowUpRight className="h-4 w-4 transition group-hover:translate-x-1 group-hover:-translate-y-1" /></div></Link>)}</div></div></main><Footer /></>;
}

function TopicDetail({ id }: { id: string }) {
  const topic = getTopic(id);
  return <><Header /><main className="bg-[#f4f8fb] pt-28 md:pt-36"><div className="container pb-20 md:pb-28"><Link href="/learn" className="inline-flex items-center gap-2 text-sm font-semibold text-cyan-700">← Back to learning</Link><div className="mt-10 grid gap-10 lg:grid-cols-[1.15fr_.85fr]"><div><Tag className="bg-cyan-100 text-cyan-800">Lesson · {topic.tag}</Tag><h1 className="mt-6 max-w-3xl font-display text-5xl font-semibold leading-[.95] tracking-[-0.065em] text-[#102333] md:text-7xl">{topic.title}</h1><p className={cx("mt-7 max-w-2xl text-lg", bodyCopyClass)}>{topic.description} This learning path turns a complex field into a clear sequence of ideas you can use, revisit and explain to someone else.</p><div className="mt-8 flex flex-wrap gap-3"><Link href={`/learn/${topic.id}/quiz`} className="inline-flex items-center gap-2 rounded-full bg-[#102333] px-5 py-3 text-sm font-semibold text-white transition hover:bg-[#163b55]">Take the quiz <ArrowUpRight className="h-4 w-4" /></Link><button className="inline-flex items-center gap-2 rounded-full border border-[#d5e4ea] bg-white px-5 py-3 text-sm font-semibold text-[#102333] hover:border-cyan-300">Save path <Bookmark className="h-4 w-4" /></button></div></div><div className={cx("relative min-h-[360px] overflow-hidden rounded-[2rem] bg-gradient-to-br p-8", topicColorMap[topic.color])}><div className="absolute -right-14 top-8 h-64 w-64 rounded-full border border-white/60" /><div className="absolute bottom-8 left-8 h-32 w-32 rounded-full border border-white/50" /><div className="relative flex h-full flex-col justify-between"><span className="grid h-14 w-14 place-items-center rounded-2xl bg-white/75 text-2xl text-[#102333]"><BookOpen className="h-6 w-6" /></span><div><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-[#102333]/50">Learning path</p><p className="mt-3 font-display text-3xl font-semibold leading-tight tracking-[-0.05em] text-[#102333]">One concept at a time.</p></div></div></div></div><div className="mt-14 grid gap-5 md:grid-cols-3"><InfoTile label="Time to complete" value="8–12 min" /><InfoTile label="Level" value="Curious beginner" /><InfoTile label="Next step" value="3 question quiz" /></div><div className="mt-14 grid gap-8 lg:grid-cols-[1.15fr_.85fr]"><article className="rounded-[2rem] border border-[#dbe7ec] bg-white p-7 md:p-10"><p className="text-[11px] font-bold uppercase tracking-[0.2em] text-cyan-700">The idea in one minute</p><h2 className="mt-4 font-display text-3xl font-semibold tracking-[-0.05em] text-[#102333]">Polar science starts with noticing patterns.</h2><p className={cx("mt-6 text-base", bodyCopyClass)}>A field station is more than a building on a map. It is a lens: a place where observations become time series, where a small change can be connected to a planetary system, and where people from different disciplines learn to read the same environment together.</p><div className="mt-8 grid gap-3 sm:grid-cols-3"><div className="rounded-2xl bg-[#e5f3f8] p-4"><p className="text-[10px] font-bold uppercase tracking-[0.15em] text-cyan-800">01</p><p className="mt-3 text-sm font-semibold text-[#294755]">Observe</p></div><div className="rounded-2xl bg-[#edf7f3] p-4"><p className="text-[10px] font-bold uppercase tracking-[0.15em] text-emerald-800">02</p><p className="mt-3 text-sm font-semibold text-[#294755]">Compare</p></div><div className="rounded-2xl bg-[#fff4df] p-4"><p className="text-[10px] font-bold uppercase tracking-[0.15em] text-amber-800">03</p><p className="mt-3 text-sm font-semibold text-[#294755]">Explain</p></div></div></article><aside className="rounded-[2rem] bg-[#102333] p-7 text-white md:p-8"><p className="text-[11px] font-bold uppercase tracking-[0.2em] text-cyan-200">Key terms</p><div className="mt-5 flex flex-wrap gap-2">{["Cryosphere", "Field notes", "Climate signal", "Observation", "Station"].map((term) => <span key={term} className="rounded-full border border-white/15 bg-white/5 px-3 py-2 text-xs text-white/70">{term}</span>)}</div><div className="mt-12 border-t border-white/10 pt-5"><p className="text-sm leading-6 text-white/55">Ready to check what you remember?</p><Link href={`/learn/${topic.id}/quiz`} className="mt-4 inline-flex items-center gap-2 rounded-full bg-cyan-300 px-4 py-2.5 text-xs font-semibold text-[#071525]">Start quiz <ArrowUpRight className="h-3.5 w-3.5" /></Link></div></aside></div></div></main><Footer /></>;
}

function Quiz({ id }: { id: string }) {
  const topic = getTopic(id);
  const [current, setCurrent] = useState(0);
  const [selected, setSelected] = useState<number | null>(null);
  const [score, setScore] = useState(0);
  const question = quizQuestions[current];
  const complete = current >= quizQuestions.length;
  const next = () => { if (selected === null) return; if (selected === question.answer) setScore((value) => value + 1); setSelected(null); setCurrent((value) => value + 1); };
  const reset = () => { setCurrent(0); setSelected(null); setScore(0); };
  return <><Header /><main className="min-h-screen bg-[#f4f8fb] pt-28 md:pt-36"><div className="container pb-20 md:pb-28"><Link href={`/learn/${topic.id}`} className="inline-flex items-center gap-2 text-sm font-semibold text-cyan-700">← Back to lesson</Link><div className="mx-auto mt-12 max-w-3xl"><div className="flex items-end justify-between gap-4"><div><p className="text-[11px] font-bold uppercase tracking-[0.2em] text-cyan-700">Quick check · {topic.title}</p><h1 className="mt-4 font-display text-4xl font-semibold tracking-[-0.06em] text-[#102333] md:text-6xl">What stayed with you?</h1></div><span className="font-display text-4xl font-semibold tracking-[-0.08em] text-[#d4e6eb]">{complete ? "03" : `0${current + 1}`}</span></div><div className="mt-8 h-1.5 overflow-hidden rounded-full bg-[#dbe7ec]"><div className="h-full rounded-full bg-cyan-500 transition-all" style={{ width: `${Math.min(100, (current / quizQuestions.length) * 100)}%` }} /></div>{complete ? <div className="mt-10 rounded-[2rem] bg-[#102333] p-8 text-white md:p-12"><div className="grid h-16 w-16 place-items-center rounded-2xl bg-cyan-300 text-[#071525]"><CheckCircle2 className="h-8 w-8" /></div><p className="mt-8 text-[11px] font-bold uppercase tracking-[0.2em] text-cyan-200">Path complete</p><h2 className="mt-3 font-display text-5xl font-semibold tracking-[-0.07em]">{score} / {quizQuestions.length}</h2><p className="mt-5 max-w-md text-base leading-7 text-white/60">Nice work. The next step is to ask the assistant about a real source and see how the ideas connect.</p><div className="mt-8 flex flex-wrap gap-3"><button onClick={reset} className="inline-flex items-center gap-2 rounded-full bg-cyan-300 px-5 py-3 text-sm font-semibold text-[#071525]">Try again <RefreshCcw className="h-4 w-4" /></button><Link href="/assistant" className="inline-flex items-center gap-2 rounded-full border border-white/15 px-5 py-3 text-sm font-semibold text-white">Ask the assistant <ArrowUpRight className="h-4 w-4" /></Link></div></div> : <div className="mt-10 rounded-[2rem] border border-[#dbe7ec] bg-white p-7 shadow-[0_20px_60px_rgba(8,28,45,0.08)] md:p-10"><div className="flex items-center justify-between text-xs font-semibold text-[#80939d]"><span>Question {current + 1} of {quizQuestions.length}</span><span>Choose one answer</span></div><h2 className="mt-8 max-w-2xl font-display text-3xl font-semibold leading-tight tracking-[-0.05em] text-[#102333] md:text-4xl">{question.question}</h2><div className="mt-8 grid gap-3">{question.options.map((option, index) => <button key={option} onClick={() => setSelected(index)} className={cx("flex items-center justify-between rounded-2xl border p-4 text-left text-sm font-semibold transition", selected === index ? "border-cyan-400 bg-cyan-50 text-cyan-900 ring-4 ring-cyan-100" : "border-[#dbe7ec] bg-white text-[#294755] hover:border-cyan-300 hover:bg-cyan-50/50")}><span className="flex items-center gap-3"><span className={cx("grid h-8 w-8 place-items-center rounded-full text-xs", selected === index ? "bg-cyan-500 text-white" : "bg-[#f4f8fb] text-[#80939d]")}>{String.fromCharCode(65 + index)}</span>{option}</span>{selected === index && <Check className="h-4 w-4 text-cyan-700" />}</button>)}</div><button onClick={next} disabled={selected === null} className="mt-8 inline-flex items-center gap-2 rounded-full bg-[#102333] px-5 py-3 text-sm font-semibold text-white transition hover:bg-[#163b55] disabled:cursor-not-allowed disabled:opacity-35">{current === quizQuestions.length - 1 ? "See result" : "Next question"}<ChevronRight className="h-4 w-4" /></button></div>}</div></div></main><Footer /></>;
}

function ExplorerMap({ preview = false }: { preview?: boolean }) {
  const [selected, setSelected] = useState("maitri");
  const station = getStation(selected);
  return <div className={cx("relative overflow-hidden rounded-[1.5rem] bg-[radial-gradient(circle_at_50%_44%,rgba(39,198,217,.16),transparent_22%),linear-gradient(135deg,#0b2439,#071525)]", preview ? "min-h-[410px]" : "min-h-[560px]")}>
    <div className="absolute inset-0 bg-[url('/manus-storage/polar-connect-map-a_68ab984b.jpg')] bg-cover bg-center opacity-75" />
    <div className="absolute inset-0 bg-gradient-to-r from-[#071525]/90 via-[#071525]/35 to-[#071525]/25" />
    <div className="absolute inset-0 opacity-20 [background-image:linear-gradient(rgba(180,230,239,.18)_1px,transparent_1px),linear-gradient(90deg,rgba(180,230,239,.18)_1px,transparent_1px)] [background-size:44px_44px]" />
    {stations.map((item) => <button key={item.id} onClick={() => setSelected(item.id)} className="group absolute z-10 -translate-x-1/2 -translate-y-1/2" style={stationCoordinates[item.id]} aria-label={`View ${item.name} station`}><span className={cx("relative mx-auto block h-4 w-4 rounded-full border-2 border-[#071525] transition duration-200 after:absolute after:left-1/2 after:top-1/2 after:h-10 after:w-10 after:-translate-x-1/2 after:-translate-y-1/2 after:rounded-full after:border after:border-cyan-200/30 after:content-[''] group-hover:scale-110", selected === item.id ? "bg-[#27c6d9] shadow-[0_0_0_5px_rgba(39,198,217,.18)]" : item.color === "amber" ? "bg-[#ffb547]" : item.color === "violet" ? "bg-[#b5a0ff]" : "bg-[#9feaf2]")} /><span className={cx("mt-3 block whitespace-nowrap text-[10px] font-bold uppercase tracking-[0.16em] transition", selected === item.id ? "text-white" : "text-white/40 group-hover:text-white/80")}>{item.name}</span></button>)}
    <div className="absolute left-5 top-5 z-20 max-w-xs md:left-8 md:top-8"><p className="text-[10px] font-bold uppercase tracking-[0.2em] text-cyan-200/70">Polar explorer</p><p className="mt-3 max-w-[175px] font-display text-xl font-semibold leading-tight tracking-[-0.05em] text-white md:max-w-[220px] md:text-2xl">Three stations. One connected system.</p></div>
    <div className="absolute bottom-4 left-4 right-4 z-20 grid gap-3 border-l-2 border-cyan-300 bg-[#071525]/90 p-4 pl-5 backdrop-blur-xl md:bottom-6 md:left-6 md:right-auto md:w-[360px]"><div className="flex items-start justify-between gap-4"><div><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-cyan-200">{station.name} · {station.region}</p><p className="mt-2 font-display text-xl font-semibold text-white">{station.description}</p></div><span className="font-display text-2xl text-white/20">{station.number}</span></div><div className="flex flex-wrap gap-x-3 gap-y-1 border-t border-white/10 pt-3">{station.facts.map((fact) => <span key={fact} className="text-[10px] text-white/55">{fact}</span>)}</div></div>
  </div>;
}

function Explorer() { return <><Header /><PageIntro eyebrow="Polar explorer" title="Follow the work to the edge of the map." description={explorerDescription} dark /><main className="bg-[#f4f8fb]"><div className="container py-12 md:py-16"><div className="mb-8 flex flex-wrap items-end justify-between gap-5"><div><p className="text-sm font-semibold text-[#102333]">India’s polar stations</p><p className="mt-1 text-xs text-[#80939d]">Select a marker to open a station brief.</p></div><div className="flex items-center gap-2 rounded-full border border-[#dbe7ec] bg-white px-3 py-2 text-xs font-semibold text-[#5e7180]"><span className="h-2 w-2 rounded-full bg-cyan-500" /> Expedition routes <span className="h-2 w-2 rounded-full bg-amber-400" /> Station network</div></div><ExplorerMap /><div className="mt-8 grid gap-4 md:grid-cols-3">{stations.map((station) => <div key={station.id} className="rounded-[1.5rem] border border-[#dbe7ec] bg-white p-5"><div className="flex items-center justify-between"><span className="text-[10px] font-bold uppercase tracking-[0.18em] text-cyan-700">{station.number} · Station</span><MapPin className="h-4 w-4 text-cyan-700" /></div><h2 className="mt-6 font-display text-2xl font-semibold tracking-[-0.05em] text-[#102333]">{station.name}</h2><p className="mt-2 text-sm text-[#80939d]">{station.region}</p><div className="mt-5 border-t border-[#e5edf0] pt-4 text-xs leading-6 text-[#5e7180]">Established {station.established}<br />{station.facts[2]}</div></div>)}</div></div></main><Footer /></>; }

function Media() {
  const [active, setActive] = useState("All");
  const categories = ["All", "Field note", "Video", "Photo essay", "News"];
  const stories = active === "All" ? mediaStories : mediaStories.filter((story) => story.type === active);
  return <><Header /><PageIntro eyebrow="Stories & media" title="The science has a human side." description={mediaDescription}><div className="mt-8 flex flex-wrap gap-2">{categories.map((category) => <button key={category} onClick={() => setActive(category)} className={cx("rounded-full px-4 py-2 text-xs font-semibold transition", active === category ? "bg-[#102333] text-white" : "border border-[#d5e4ea] bg-white text-[#5e7180] hover:border-cyan-300 hover:bg-cyan-50")}>{category}</button>)}</div></PageIntro><main className="bg-[#f4f8fb]"><div className="container py-12 md:py-16"><div className="grid gap-5 md:grid-cols-2">{stories.map((story, index) => <article key={story.id} className={cx("group relative min-h-[360px] overflow-hidden rounded-[2rem] bg-gradient-to-br p-7 text-white transition duration-300 hover:-translate-y-1 hover:shadow-[0_24px_70px_rgba(8,28,45,0.16)]", story.gradient, index === 0 && "md:row-span-2 md:min-h-[740px]")}><div className="absolute inset-0 bg-[radial-gradient(circle_at_75%_18%,rgba(255,255,255,.18),transparent_28%)]" /><div className="absolute bottom-[-12%] right-[-8%] h-64 w-64 rounded-full border border-white/15" /><div className="relative flex h-full flex-col justify-between"><div className="flex items-center justify-between"><Tag className="bg-white/10 text-white/70">{story.type}</Tag><span className="text-sm text-white/50">{story.eyebrow}</span></div><div><h2 className={cx("max-w-xl font-display font-semibold leading-[.95] tracking-[-0.06em]", index === 0 ? "text-5xl md:text-7xl" : "text-4xl")}>{story.title}</h2><p className="mt-5 max-w-md text-sm leading-6 text-white/60">{story.summary}</p><button className="mt-7 inline-flex items-center gap-2 text-sm font-semibold text-cyan-200 transition group-hover:text-white">Open story <ArrowUpRight className="h-4 w-4 transition group-hover:translate-x-1 group-hover:-translate-y-1" /></button></div></div></article>)}</div><div className="mt-16 grid gap-5 md:grid-cols-3"><div className="rounded-[1.5rem] bg-[#102333] p-6 text-white"><Radio className="h-6 w-6 text-cyan-300" /><h3 className="mt-10 font-display text-2xl font-semibold tracking-[-0.05em]">Field notes</h3><p className="mt-3 text-sm leading-6 text-white/55">Short observations from long journeys.</p></div><div className="rounded-[1.5rem] border border-[#dbe7ec] bg-white p-6"><CameraIcon /><h3 className="mt-10 font-display text-2xl font-semibold tracking-[-0.05em] text-[#102333]">Photo essays</h3><p className="mt-3 text-sm leading-6 text-[#5e7180]">See the textures of ice, rock, sea and sky.</p></div><div className="rounded-[1.5rem] border border-[#dbe7ec] bg-white p-6"><Play className="h-6 w-6 text-cyan-700" /><h3 className="mt-10 font-display text-2xl font-semibold tracking-[-0.05em] text-[#102333]">Short films</h3><p className="mt-3 text-sm leading-6 text-[#5e7180]">A clear window into life at the stations.</p></div></div></div></main><Footer /></>;
}

function CameraIcon() { return <span className="grid h-6 w-6 place-items-center rounded-md border-2 border-cyan-700 text-[10px] text-cyan-700">▧</span>; }

function Studio() {
  const [step, setStep] = useState(0);
  const [channel, setChannel] = useState(outreachChannels[0].id);
  const [drafts, setDrafts] = useState<Record<string, string>>(() => Object.fromEntries(outreachChannels.map((item) => [item.id, item.content])));
  const [audience, setAudience] = useState("Public audience");
  const [tone, setTone] = useState("Clear and grounded");
  const [language, setLanguage] = useState("English");
  const [selectedChannels, setSelectedChannels] = useState(["web", "linkedin", "instagram"]);
  const [verifiedClaims, setVerifiedClaims] = useState([true, true, false]);
  const [notice, setNotice] = useState("");
  const noticeTimer = useRef<number | null>(null);
  const activeChannel = outreachChannels.find((item) => item.id === channel) ?? outreachChannels[0];
  const source = repositoryItems[0];
  const sourceFacts = ["Atmospheric observations near Maitri", "Glaciology and seasonal snow accumulation", "Biological sampling across Schirmacher Oasis"];
  const showNotice = (message: string, duration = 2600) => {
    if (noticeTimer.current) window.clearTimeout(noticeTimer.current);
    setNotice(message);
    noticeTimer.current = window.setTimeout(() => setNotice(""), duration);
  };
  useEffect(() => () => { if (noticeTimer.current) window.clearTimeout(noticeTimer.current); }, []);
  const update = (value: string) => setDrafts((current) => ({ ...current, [channel]: value }));
  const toggleChannel = (id: string) => setSelectedChannels((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]);
  const stepDescriptions = ["Add a trusted report, dataset, media file or URL.", "Extract facts, entities and claims from the source.", "Choose the people, channels and voice for the output.", "Review every draft with its supporting evidence.", "Approve, schedule or export the final content."];
  const canAdvance = step === 1 ? verifiedClaims.filter(Boolean).length >= 2 : step === 2 ? selectedChannels.length > 0 : true;
  return <><Header /><PageIntro eyebrow="Outreach studio" title="One trusted source. Every useful format." description={studioDescription} dark><div className="mt-8 flex flex-wrap gap-2"><Tag className="text-cyan-200">Source-to-story workflow</Tag><Tag className="text-white/60">Human review required</Tag></div></PageIntro><main className="bg-[#f4f8fb]"><div className="container py-12 md:py-16">
    <section className="rounded-[2rem] border border-[#dbe7ec] bg-white p-5 shadow-[0_20px_60px_rgba(8,28,45,0.08)] md:p-8">
      <div className="flex flex-col justify-between gap-6 border-b border-[#e5edf0] pb-8 lg:flex-row lg:items-start"><div><p className="text-[10px] font-bold uppercase tracking-[0.2em] text-cyan-700">Automation pipeline</p><h2 className="mt-3 font-display text-3xl font-semibold tracking-[-0.05em] text-[#102333]">From evidence to outreach.</h2><p className="mt-2 max-w-xl text-sm leading-6 text-[#80939d]">A guided workflow keeps every generated message connected to the institutional source that supports it.</p></div><div className="border-l-2 border-cyan-300 bg-cyan-50/60 px-4 py-3 text-xs text-[#5e7180]"><span className="font-bold text-cyan-800">SOURCE ID</span><br />NCPOR-EXP-43 · verified record</div></div>
      <div className="mt-8 grid gap-3 md:grid-cols-5">{studioSteps.map((item, index) => <button key={item} onClick={() => setStep(index)} className={cx("group relative rounded-2xl p-3 text-left transition", step === index ? "bg-[#102333] text-white shadow-lg" : index < step ? "bg-cyan-50 text-[#102333]" : "bg-[#f4f8fb] text-[#80939d] hover:bg-cyan-50")}><div className="flex items-center gap-3"><span className={cx("grid h-8 w-8 shrink-0 place-items-center rounded-xl border text-xs font-bold", step === index ? "border-cyan-300 bg-cyan-300 text-[#071525]" : index < step ? "border-cyan-400 bg-cyan-400 text-white" : "border-[#dbe7ec] bg-white")}>{index < step ? <Check className="h-4 w-4" /> : index + 1}</span><span className="text-xs font-semibold">{item}</span></div><p className={cx("mt-3 pl-11 text-[10px] leading-4", step === index ? "text-white/55" : "text-current/60")}>{stepDescriptions[index]}</p></button>)}</div>
    </section>
    <div className="mt-6 grid gap-5 lg:grid-cols-[280px_1fr]">
      <aside className="rounded-[1.5rem] bg-[#102333] p-5 text-white"><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-cyan-200/70">Workflow context</p><div className="mt-5 border-l border-cyan-300/50 pl-4"><p className="text-xs font-semibold text-white/80">{source.title}</p><p className="mt-2 text-[11px] leading-5 text-white/45">{source.summary}</p><div className="mt-4 flex flex-wrap gap-1.5">{source.topics.map((topic) => <span key={topic} className="border border-white/10 px-2 py-1 text-[9px] uppercase tracking-[0.1em] text-white/55">{topic}</span>)}</div></div><div className="mt-8 border-t border-white/10 pt-5"><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-white/35">Integrity checks</p><div className="mt-4 grid gap-3 text-xs text-white/65"><span className="flex items-center gap-2"><CheckCircle2 className="h-4 w-4 text-cyan-300" /> Source linked</span><span className="flex items-center gap-2"><CheckCircle2 className="h-4 w-4 text-cyan-300" /> Claims traceable</span><span className="flex items-center gap-2"><Clock3 className="h-4 w-4 text-amber-300" /> Human review pending</span></div></div></aside>
      <section className="min-w-0 rounded-[1.5rem] border border-[#dbe7ec] bg-white p-5 md:p-8">
        {step === 0 && <div><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-cyan-700">01 · Add a source</p><h3 className="mt-2 font-display text-2xl font-semibold tracking-[-0.04em] text-[#102333]">Start with a trusted record.</h3><p className="mt-2 max-w-xl text-sm leading-6 text-[#80939d]">Import the material you want to turn into public-facing stories. The original record remains attached throughout the workflow.</p></div><button onClick={() => showNotice("File picker is ready for the production ingestion service.")} className="inline-flex shrink-0 items-center justify-center gap-2 rounded-full bg-[#102333] px-4 py-2.5 text-xs font-semibold text-white hover:bg-[#163b55]"><Database className="h-4 w-4" /> Import source</button></div><div className="mt-8 grid gap-3 sm:grid-cols-3">{["PDF or report", "Dataset or spreadsheet", "Media or source URL"].map((item, index) => <div key={item} className="border border-dashed border-[#c8dce3] bg-[#f8fbfc] p-5"><span className="text-2xl text-cyan-700">{["▱", "⌁", "▶"][index]}</span><p className="mt-4 text-sm font-semibold text-[#102333]">{item}</p><p className="mt-2 text-xs leading-5 text-[#80939d]">{["Extract findings, authors and dates.", "Read columns, units and observations.", "Attach captions, credits and context."][index]}</p></div>)}</div><div className="mt-6 border-l-2 border-cyan-300 bg-cyan-50/60 px-4 py-3 text-xs leading-5 text-[#5e7180]"><strong className="text-[#102333]">Selected source:</strong> {source.title} · {source.meta} · {source.year}</div></div>}
        {step === 1 && <div><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-cyan-700">02 · Analyse evidence</p><h3 className="mt-2 font-display text-2xl font-semibold tracking-[-0.04em] text-[#102333]">Make the source understandable.</h3><p className="mt-2 max-w-xl text-sm leading-6 text-[#80939d]">The analysis layer extracts the facts that can safely travel into a public story. Confirm the claims before generation.</p><div className="mt-7 grid gap-4 md:grid-cols-3"><div className="border border-[#dbe7ec] bg-[#f8fbfc] p-4"><p className="text-[10px] font-bold uppercase tracking-[0.14em] text-cyan-700">Entities</p><p className="mt-3 text-sm font-semibold text-[#102333]">Maitri · Antarctica · Expedition 43</p></div><div className="border border-[#dbe7ec] bg-[#f8fbfc] p-4"><p className="text-[10px] font-bold uppercase tracking-[0.14em] text-cyan-700">Topics</p><p className="mt-3 text-sm font-semibold text-[#102333]">Atmosphere · Glaciology · Biology</p></div><div className="border border-[#dbe7ec] bg-[#f8fbfc] p-4"><p className="text-[10px] font-bold uppercase tracking-[0.14em] text-cyan-700">Reading signal</p><p className="mt-3 text-sm font-semibold text-[#102333]">86 pages · 3 evidence clusters</p></div></div><div className="mt-7"><div className="flex items-center justify-between"><p className="text-sm font-semibold text-[#102333]">Claims to carry forward</p><span className="text-xs text-[#80939d]">{verifiedClaims.filter(Boolean).length}/3 verified</span></div><div className="mt-3 grid gap-2">{sourceFacts.map((fact, index) => <label key={fact} className={cx("flex cursor-pointer items-start gap-3 border p-4 transition", verifiedClaims[index] ? "border-cyan-200 bg-cyan-50/50" : "border-[#dbe7ec] bg-white")}><input type="checkbox" checked={verifiedClaims[index]} onChange={() => setVerifiedClaims((current) => current.map((value, claimIndex) => claimIndex === index ? !value : value))} className="mt-0.5 h-4 w-4 accent-cyan-600" /><span><span className="block text-sm font-semibold text-[#102333]">{fact}</span><span className="mt-1 block text-xs text-[#80939d]">Supported by the selected expedition record.</span></span><span className="ml-auto text-[10px] font-bold uppercase tracking-[0.12em] text-cyan-700">{verifiedClaims[index] ? "Grounded" : "Review"}</span></label>)}</div></div></div>}
        {step === 2 && <div><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-cyan-700">03 · Configure generation</p><h3 className="mt-2 font-display text-2xl font-semibold tracking-[-0.04em] text-[#102333]">Choose who should hear the story.</h3><p className="mt-2 max-w-xl text-sm leading-6 text-[#80939d]">One source can become different kinds of useful content. Set the context once, then generate every selected channel.</p><div className="mt-7 grid gap-5 md:grid-cols-3"><label className="grid gap-2 text-xs font-semibold text-[#5e7180]">Audience<select value={audience} onChange={(event) => setAudience(event.target.value)} className="rounded-xl border border-[#dbe7ec] bg-white px-3 py-3 text-sm text-[#102333] outline-none focus:border-cyan-400"><option>Public audience</option><option>Students · Class 10</option><option>Researchers</option><option>Media teams</option></select></label><label className="grid gap-2 text-xs font-semibold text-[#5e7180]">Voice<select value={tone} onChange={(event) => setTone(event.target.value)} className="rounded-xl border border-[#dbe7ec] bg-white px-3 py-3 text-sm text-[#102333] outline-none focus:border-cyan-400"><option>Clear and grounded</option><option>Warm and curious</option><option>Institutional brief</option><option>Short social caption</option></select></label><label className="grid gap-2 text-xs font-semibold text-[#5e7180]">Language<select value={language} onChange={(event) => setLanguage(event.target.value)} className="rounded-xl border border-[#dbe7ec] bg-white px-3 py-3 text-sm text-[#102333] outline-none focus:border-cyan-400"><option>English</option><option>Hindi</option><option>English + Hindi</option></select></label></div><div className="mt-7"><p className="text-sm font-semibold text-[#102333]">Generate for channels</p><div className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{outreachChannels.map((item) => <button key={item.id} onClick={() => toggleChannel(item.id)} className={cx("flex items-center justify-between border p-4 text-left transition", selectedChannels.includes(item.id) ? "border-cyan-300 bg-cyan-50" : "border-[#dbe7ec] bg-white hover:border-cyan-200")}><span className="flex items-center gap-3"><span className="grid h-7 w-7 place-items-center rounded-lg bg-[#102333] text-xs text-white">{item.icon}</span><span className="text-sm font-semibold text-[#102333]">{item.label}</span></span><span className={cx("grid h-5 w-5 place-items-center rounded-full border text-[10px]", selectedChannels.includes(item.id) ? "border-cyan-500 bg-cyan-500 text-white" : "border-[#c8dce3] text-transparent")}>✓</span></button>)}</div></div><div className="mt-6 border-l-2 border-cyan-300 bg-cyan-50/60 px-4 py-3 text-xs leading-5 text-[#5e7180]">Generating for <strong className="text-[#102333]">{audience}</strong> · {tone} · {language} · {selectedChannels.length} channels selected.</div></div>}
        {step === 3 && <div><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-cyan-700">04 · Review grounded outputs</p><h3 className="mt-2 font-display text-2xl font-semibold tracking-[-0.04em] text-[#102333]">Every channel, one evidence trail.</h3><p className="mt-2 max-w-xl text-sm leading-6 text-[#80939d]">Edit the output, inspect its source context, and keep unsupported claims out of the public record.</p></div><button onClick={() => showNotice("All selected channels regenerated from the verified source.")} className="inline-flex shrink-0 items-center justify-center gap-2 rounded-full border border-[#dbe7ec] px-4 py-2.5 text-xs font-semibold text-[#5e7180] hover:border-cyan-300"><RefreshCcw className="h-4 w-4" /> Regenerate all</button></div><div className="mt-7 flex gap-2 overflow-x-auto border-b border-[#e5edf0] pb-2">{outreachChannels.filter((item) => selectedChannels.includes(item.id)).map((item) => <button key={item.id} onClick={() => setChannel(item.id)} className={cx("shrink-0 border-b-2 px-3 py-2 text-xs font-semibold", channel === item.id ? "border-cyan-500 text-cyan-800" : "border-transparent text-[#80939d]")}>{item.label}</button>)}</div><div className="mt-5 grid gap-5 lg:grid-cols-[1fr_220px]"><div><div className="flex items-center justify-between gap-3"><span className="text-[10px] font-bold uppercase tracking-[0.16em] text-cyan-700">{activeChannel.label} · editable draft</span><span className="text-xs text-[#80939d]">{drafts[channel].length} characters</span></div><textarea value={drafts[channel]} onChange={(event) => update(event.target.value)} className="mt-3 min-h-[240px] w-full resize-y rounded-2xl border border-[#dbe7ec] bg-[#f8fbfc] p-5 text-sm leading-7 text-[#294755] outline-none transition focus:border-cyan-400 focus:ring-4 focus:ring-cyan-100" /><div className="mt-3 flex flex-wrap gap-2"><button onClick={() => { navigator.clipboard?.writeText(drafts[channel]); showNotice("Draft copied to clipboard."); }} className="rounded-full border border-[#dbe7ec] px-4 py-2 text-xs font-semibold text-[#5e7180] hover:border-cyan-300">Copy draft</button><button onClick={() => showNotice("Draft saved to the review queue.")} className="rounded-full bg-[#102333] px-4 py-2 text-xs font-semibold text-white hover:bg-[#163b55]">Save review version</button></div></div><aside className="border-l border-[#e5edf0] pl-5"><p className="text-[10px] font-bold uppercase tracking-[0.16em] text-cyan-700">Evidence trail</p><p className="mt-3 text-xs leading-5 text-[#80939d]">This output is grounded in:</p><div className="mt-3 grid gap-2">{sourceFacts.slice(0, 2).map((fact) => <div key={fact} className="flex gap-2 text-xs leading-5 text-[#294755]"><CheckCircle2 className="mt-0.5 h-3.5 w-3.5 shrink-0 text-cyan-600" />{fact}</div>)}</div><div className="mt-5 border-t border-[#e5edf0] pt-4 text-xs text-[#80939d]">Source record<br /><strong className="text-[#102333]">{source.title}</strong></div></aside></div></div>}
        {step === 4 && <div><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-cyan-700">05 · Approve and distribute</p><h3 className="mt-2 font-display text-2xl font-semibold tracking-[-0.04em] text-[#102333]">Ready for a human decision.</h3><p className="mt-2 max-w-xl text-sm leading-6 text-[#80939d]">Nothing publishes automatically. Choose whether to keep the approved content as an export, schedule it, or hand it to a connected channel.</p><div className="mt-7 grid gap-3 md:grid-cols-3">{[{ title: "Export package", copy: "Download drafts, claims and source links.", action: "Export content" }, { title: "Schedule outreach", copy: "Choose a date and prepare the publishing queue.", action: "Schedule draft" }, { title: "Publish when connected", copy: "Send to an approved institutional channel.", action: "Connect channel" }].map((item) => <div key={item.title} className="border border-[#dbe7ec] bg-[#f8fbfc] p-5"><p className="text-sm font-semibold text-[#102333]">{item.title}</p><p className="mt-2 min-h-10 text-xs leading-5 text-[#80939d]">{item.copy}</p><button onClick={() => showNotice(`${item.action} is ready for the production connector.`)} className="mt-5 rounded-full border border-[#b9d7df] bg-white px-3 py-2 text-xs font-semibold text-[#102333] hover:border-cyan-400">{item.action} <ArrowUpRight className="ml-1 inline h-3.5 w-3.5" /></button></div>)}</div><div className="mt-7 flex items-center gap-3 border-l-2 border-emerald-400 bg-emerald-50 px-4 py-3 text-xs leading-5 text-emerald-900"><CheckCircle2 className="h-5 w-5 shrink-0" /><span><strong>Review complete.</strong> {selectedChannels.length} channel drafts are connected to the verified source and ready for the next operational step.</span></div></div>}
        {notice && <div className="mt-8 rounded-xl bg-cyan-50 px-4 py-3 text-xs font-semibold text-cyan-900" aria-live="polite">{notice}</div>}
        <div className="mt-8 flex flex-col-reverse justify-between gap-3 border-t border-[#e5edf0] pt-5 sm:flex-row sm:items-center"><button onClick={() => setStep((current) => Math.max(0, current - 1))} disabled={step === 0} className="rounded-full border border-[#dbe7ec] px-4 py-2.5 text-xs font-semibold text-[#5e7180] disabled:cursor-not-allowed disabled:opacity-35">Back</button><div className="flex gap-2"><button onClick={() => showNotice("Workflow saved to the local prototype workspace.")} className="rounded-full px-4 py-2.5 text-xs font-semibold text-[#80939d] hover:text-[#102333]">Save progress</button>{step < 4 && <button onClick={() => { if (!canAdvance) { showNotice(step === 1 ? "Verify at least two evidence claims before continuing." : "Select at least one channel before continuing."); return; } setStep((current) => Math.min(4, current + 1)); }} className="rounded-full bg-[#102333] px-5 py-2.5 text-xs font-semibold text-white hover:bg-[#163b55]">Continue to {studioSteps[step + 1]} <ArrowUpRight className="ml-1 inline h-3.5 w-3.5" /></button>}</div></div>
      </section>
    </div>
  </div></main><Footer /></>;
}
function About() { return <><Header /><PageIntro eyebrow="About Polar Connect" title="A public layer for a polar science ecosystem." description={aboutDescription}><div className="mt-8 flex flex-wrap gap-2"><Tag className="text-[#102333]">NCPOR</Tag><Tag className="text-[#5e7180]">Ministry of Earth Sciences</Tag></div></PageIntro><main className="bg-[#f4f8fb]"><div className="container py-12 md:py-16"><div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><article className="rounded-[2rem] bg-[#102333] p-8 text-white md:p-12"><p className="text-[11px] font-bold uppercase tracking-[0.2em] text-cyan-200">Why it exists</p><h2 className="mt-5 max-w-xl font-display text-4xl font-semibold leading-tight tracking-[-0.06em] md:text-6xl">Make the record easier to enter.</h2><p className="mt-6 max-w-xl text-base leading-7 text-white/60">India’s polar research creates knowledge for many audiences. Polar Connect is the connective tissue between the source record, the curious student, the researcher looking for context and the outreach team shaping the next story.</p><div className="mt-10 grid gap-3 sm:grid-cols-3"><div className="rounded-2xl border border-white/10 bg-white/5 p-4"><Database className="h-5 w-5 text-cyan-200" /><p className="mt-7 text-sm font-semibold">Archive</p></div><div className="rounded-2xl border border-white/10 bg-white/5 p-4"><GraduationCap className="h-5 w-5 text-cyan-200" /><p className="mt-7 text-sm font-semibold">Explain</p></div><div className="rounded-2xl border border-white/10 bg-white/5 p-4"><Radio className="h-5 w-5 text-cyan-200" /><p className="mt-7 text-sm font-semibold">Share</p></div></div></article><div className="grid gap-5"><InfoTile label="Audience one" value="Researchers & teams" /><InfoTile label="Audience two" value="Students & educators" /><InfoTile label="Audience three" value="Public & media" /></div></div><div className="mt-10 grid gap-5 md:grid-cols-3"><InfoBlock id="provenance" icon={<FileText />} title="Content provenance" text="Seeded records in this prototype are illustrative. In production, every answer and story will link to a verified institutional source." /><InfoBlock id="accessibility" icon={<Layers3 />} title="Designed for access" text="Polar Connect is designed with keyboard navigation, readable contrast and reduced-motion preferences in mind." /><InfoBlock id="contact" icon={<MessageCircle />} title="Built to grow" text="For institutional contributions, corrections or outreach partnerships, connect with the NCPOR knowledge team." /></div></div></main><Footer /></>; }

function InfoBlock({ id, icon, title, text }: { id: string; icon: React.ReactNode; title: string; text: string }) { return <section id={id} className="rounded-[1.5rem] border border-[#dbe7ec] bg-white p-6"><span className="grid h-10 w-10 place-items-center rounded-xl bg-cyan-50 text-cyan-700">{icon}</span><h2 className="mt-8 font-display text-2xl font-semibold tracking-[-0.05em] text-[#102333]">{title}</h2><p className={cx("mt-3", bodyCopyClass)}>{text}</p></section>; }

function NotFound() { return <><Header /><main className="grid min-h-screen place-items-center bg-[#f4f8fb] px-5 pt-20"><div className="max-w-lg text-center"><p className="text-[11px] font-bold uppercase tracking-[0.22em] text-cyan-700">404 · Off the map</p><h1 className="mt-5 font-display text-5xl font-semibold tracking-[-0.07em] text-[#102333]">This polar coordinate is off the map.</h1><p className={cx("mt-5", bodyCopyClass)}>Use the navigation to return to the knowledge atlas.</p><Link href="/" className="mt-8 inline-flex items-center gap-2 rounded-full bg-[#102333] px-5 py-3 text-sm font-semibold text-white">Return home <ArrowUpRight className="h-4 w-4" /></Link></div></main><Footer /></>; }

function App() {
  useEffect(() => { document.title = "Polar Connect — India’s polar science, in the open."; }, []);
  return <Switch><Route path="/" component={Home} /><Route path="/repository" component={Repository} /><Route path="/repository/:id">{(params) => <RepositoryDetail id={params.id} />}</Route><Route path="/assistant" component={Assistant} /><Route path="/learn" component={Learn} /><Route path="/learn/:id/quiz">{(params) => <Quiz id={params.id} />}</Route><Route path="/learn/:id">{(params) => <TopicDetail id={params.id} />}</Route><Route path="/explorer" component={Explorer} /><Route path="/media" component={Media} /><Route path="/studio" component={Studio} /><Route path="/about" component={About} /><Route component={NotFound} /></Switch>;
}

export default App;
